   145	/*!
   146	 * Multiply two color components. Really expects the arguments to be
   147	 * 8-bit quantities.
   148	 * \param a first minuend.
   149	 * \param b second minuend.
   150	 * \return product of arguments.
   151	 */
   152	inline int INT_MULT(int a, int b)
   153	{
   154	    int c = a * b + 0x80;
   155	    return ((c >> 8) + c) >> 8;
   156	}
   157	
   158	/*!
   159	 * Blend the two color components in the proportion alpha:
   160	 *
   161	 * result = alpha a + ( 1 - alpha ) b
   162	 *
   163	 * \param a first component.
   164	 * \param b second component.
   165	 * \param alpha blend proportion.
   166	 * \return blended color components.
   167	 */
   168	
   169	inline int INT_BLEND(int a, int b, int alpha)
   170	{
   171	    return INT_MULT(a - b, alpha) + b;
   172	}
