   176	/*!
   177	 * Convert a color in RGB space to HSV space (Hue, Saturation, Value).
   178	 * \param red the red component (modified in place).
   179	 * \param green the green component (modified in place).
   180	 * \param blue the blue component (modified in place).
   181	 */
   182	static void RGBTOHSV(uchar &red, uchar &green, uchar &blue)
   183	{
   184	    int r, g, b;
   185	    double h, s, v;
   186	    int min, max;
   187	
   188	    h = 0.;
   189	
   190	    r = red;
   191	    g = green;
   192	    b = blue;
   193	
   194	    if (r > g) {
   195	        max = qMax(r, b);
   196	        min = qMin(g, b);
   197	    } else {
   198	        max = qMax(g, b);
   199	        min = qMin(r, b);
   200	    }
   201	
   202	    v = max;
   203	
   204	    if (max != 0) {
   205	        s = ((max - min) * 255) / (double)max;
   206	    } else {
   207	        s = 0;
   208	    }
   209	
   210	    if (s == 0) {
   211	        h = 0;
   212	    } else {
   213	        int delta = max - min;
   214	        if (r == max) {
   215	            h = (g - b) / (double)delta;
   216	        } else if (g == max) {
   217	            h = 2 + (b - r) / (double)delta;
   218	        } else if (b == max) {
   219	            h = 4 + (r - g) / (double)delta;
   220	        }
   221	        h *= 42.5;
   222	
   223	        if (h < 0) {
   224	            h += 255;
   225	        }
   226	        if (h > 255) {
   227	            h -= 255;
   228	        }
   229	    }
   230	
   231	    red   = (uchar)h;
   232	    green = (uchar)s;
   233	    blue  = (uchar)v;
   234	}
