   236	/*!
   237	 * Convert a color in HSV space to RGB space.
   238	 * \param hue the hue component (modified in place).
   239	 * \param saturation the saturation component (modified in place).
   240	 * \param value the value component (modified in place).
   241	 */
   242	static void HSVTORGB(uchar &hue, uchar &saturation, uchar &value)
   243	{
   244	    if (saturation == 0) {
   245	        hue        = value;
   246	        saturation = value;
   247	        //value      = value;
   248	    } else {
   249	        double h = hue * 6. / 255.;
   250	        double s = saturation / 255.;
   251	        double v = value / 255.;
   252	
   253	        double f = h - (int)h;
   254	        double p = v * (1. - s);
   255	        double q = v * (1. - (s * f));
   256	        double t = v * (1. - (s * (1. - f)));
   257	
   258	        // Worth a note here that gcc 2.96 will generate different results
   259	        // depending on optimization mode on i386.
   260	
   261	        switch ((int)h) {
   262	        case 0:
   263	            hue        = (uchar)(v * 255);
   264	            saturation = (uchar)(t * 255);
   265	            value      = (uchar)(p * 255);
   266	            break;
   267	        case 1:
   268	            hue        = (uchar)(q * 255);
   269	            saturation = (uchar)(v * 255);
   270	            value      = (uchar)(p * 255);
   271	            break;
   272	        case 2:
   273	            hue        = (uchar)(p * 255);
   274	            saturation = (uchar)(v * 255);
   275	            value      = (uchar)(t * 255);
   276	            break;
   277	        case 3:
   278	            hue        = (uchar)(p * 255);
   279	            saturation = (uchar)(q * 255);
   280	            value      = (uchar)(v * 255);
   281	            break;
   282	        case 4:
   283	            hue        = (uchar)(t * 255);
   284	            saturation = (uchar)(p * 255);
   285	            value      = (uchar)(v * 255);
   286	            break;
   287	        case 5:
   288	            hue        = (uchar)(v * 255);
   289	            saturation = (uchar)(p * 255);
   290	            value      = (uchar)(q * 255);
   291	        }
   292	    }
   293	}
