   295	/*!
   296	 * Convert a color in RGB space to HLS space (Hue, Lightness, Saturation).
   297	 * \param red the red component (modified in place).
   298	 * \param green the green component (modified in place).
   299	 * \param blue the blue component (modified in place).
   300	 */
   301	static void RGBTOHLS(uchar &red, uchar &green, uchar &blue)
   302	{
   303	    int r = red;
   304	    int g = green;
   305	    int b = blue;
   306	
   307	    int min, max;
   308	
   309	    if (r > g) {
   310	        max = qMax(r, b);
   311	        min = qMin(g, b);
   312	    } else {
   313	        max = qMax(g, b);
   314	        min = qMin(r, b);
   315	    }
   316	
   317	    double h;
   318	    double l = (max + min) / 2.;
   319	    double s;
   320	
   321	    if (max == min) {
   322	        s = 0.;
   323	        h = 0.;
   324	    } else {
   325	        int delta = max - min;
   326	
   327	        if (l < 128) {
   328	            s = 255 * (double)delta / (double)(max + min);
   329	        } else {
   330	            s = 255 * (double)delta / (double)(511 - max - min);
   331	        }
   332	
   333	        if (r == max) {
   334	            h = (g - b) / (double)delta;
   335	        } else if (g == max) {
   336	            h = 2 + (b - r) / (double)delta;
   337	        } else {
   338	            h = 4 + (r - g) / (double)delta;
   339	        }
   340	
   341	        h *= 42.5;
   342	
   343	        if (h < 0) {
   344	            h += 255;
   345	        } else if (h > 255) {
   346	            h -= 255;
   347	        }
   348	    }
   349	
   350	    red   = (uchar)h;
   351	    green = (uchar)l;
   352	    blue  = (uchar)s;
   353	}
