   355	/*!
   356	 * Implement the HLS "double hex-cone".
   357	 * \param n1 lightness fraction (?)
   358	 * \param n2 saturation fraction (?)
   359	 * \param hue hue "angle".
   360	 * \return HLS value.
   361	 */
   362	static int HLSVALUE(double n1, double n2, double hue)
   363	{
   364	    double value;
   365	
   366	    if (hue > 255) {
   367	        hue -= 255;
   368	    } else if (hue < 0) {
   369	        hue += 255;
   370	    }
   371	
   372	    if (hue < 42.5) {
   373	        value = n1 + (n2 - n1) * (hue / 42.5);
   374	    } else if (hue < 127.5) {
   375	        value = n2;
   376	    } else if (hue < 170) {
   377	        value = n1 + (n2 - n1) * ((170 - hue) / 42.5);
   378	    } else {
   379	        value = n1;
   380	    }
   381	
   382	    return (int)(value * 255);
   383	}
   384	
   385	/*!
   386	 * Convert a color in HLS space to RGB space.
   387	 * \param hue the hue component (modified in place).
   388	 * \param lightness the lightness component (modified in place).
   389	 * \param saturation the saturation component (modified in place).
   390	 */
   391	static void HLSTORGB(uchar &hue, uchar &lightness, uchar &saturation)
   392	{
   393	    double h = hue;
   394	    double l = lightness;
   395	    double s = saturation;
   396	
   397	    if (s == 0) {
   398	        hue        = (uchar)l;
   399	        lightness  = (uchar)l;
   400	        saturation = (uchar)l;
   401	    } else {
   402	        double m1, m2;
   403	
   404	        if (l < 128) {
   405	            m2 = (l * (255 + s)) / 65025.;
   406	        } else {
   407	            m2 = (l + s - (l * s) / 255.) / 255.;
   408	        }
   409	
   410	        m1 = (l / 127.5) - m2;
   411	
   412	        hue        = HLSVALUE(m1, m2, h + 85);
   413	        lightness  = HLSVALUE(m1, m2, h);
   414	        saturation = HLSVALUE(m1, m2, h - 85);
   415	    }
   416	}
